/* MindReader service worker. Generated by scripts/gen-sw.mjs. */
const VERSION = "__VERSION__";
const SHELL = `shell-${VERSION}`;
const IMAGES = "images-v1";
const PRECACHE = __PRECACHE__;

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(SHELL).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== SHELL && k !== IMAGES).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

async function trimImages() {
  const cache = await caches.open(IMAGES);
  const keys = await cache.keys();
  for (const k of keys.slice(0, Math.max(0, keys.length - 300))) await cache.delete(k);
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.pathname.startsWith("/v1/")) return; // the API is always live
  if (url.origin === location.origin && url.pathname.startsWith("/img/")) {
    event.respondWith(
      caches.open(IMAGES).then(async (cache) => {
        const hit = await cache.match(req);
        if (hit) return hit;
        const res = await fetch(req);
        if (res.ok) {
          cache.put(req, res.clone());
          trimImages();
        }
        return res;
      }),
    );
    return;
  }
  if (req.mode === "navigate") {
    // Network first for pages, so a new deploy shows up; the cached shell when offline.
    event.respondWith(
      fetch(req).catch(async () => (await caches.match(url.pathname, { ignoreSearch: true })) || caches.match("/")),
    );
    return;
  }
  event.respondWith(caches.match(req).then((hit) => hit || fetch(req)));
});
